import { MeshPhysicalNodeMaterial } from 'three/webgpu';
import { float, texture, positionLocal, normalLocal, uv, uniform, vec3, mix, clamp, mul, add, sub } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, Color, EdgesGeometry, LineSegments, LineBasicMaterial } = ctx.THREE;

  const group = new Group();

  /* ── card geometry ── */
  const W = 1.75;
  const H = 1.0;
  const SEG = 64;
  const geo = new PlaneGeometry(W, H, SEG, SEG);
  const edgeGeo = new EdgesGeometry(geo);

  /* ── machined PBR surface ── */
  const mat = new MeshPhysicalNodeMaterial({
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.15,
    clearcoatRoughness: 0.3,
    envMapIntensity: 0.8,
    color: new Color('#e8ecf2'),
  });

  const card = new Mesh(geo, mat);
  card.userData.isInteractive = true;
  card.position.y = 0.4; // entrance offset
  group.add(card);

  /* ── load textures ── */
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      mat.map = tex;
      mat.needsUpdate = true;
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
      const dVal = texture(depthTex).sample(uv()).r;
      const disp = dVal.mul(0.04);
      mat.positionNode = positionLocal.add(normalLocal.mul(disp));
    });
  }

  /* ── accent edge (signal red on focus) ── */
  const edgeMat = new LineBasicMaterial({
    color: new Color('#ff2a38'),
    transparent: true,
    opacity: 0,
  });
  const edgeLine = new LineSegments(edgeGeo, edgeMat);
  edgeLine.position.z = 0.005;
  group.add(edgeLine);

  /* ── entrance animation ── */
  gsap.to(card.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
    delay: 0.1,
  });

  /* ── interaction handlers ── */
  group.userData.handlers = {
    hover: {
      enter: () => {
        gsap.to(card.position, { y: 0.15, duration: 0.3, ease: 'power2.out' });
        gsap.to(edgeMat, { opacity: 1, duration: 0.3, ease: 'power2.out' });
      },
      leave: () => {
        gsap.to(card.position, { y: 0, duration: 0.3, ease: 'power2.out' });
        gsap.to(edgeMat, { opacity: 0, duration: 0.3, ease: 'power2.out' });
      },
    },
    click: {
      trigger: () => {
        const tl = gsap.timeline({
          onComplete: () => ctx.emit('navigate', { to: 'hub-features.select' }),
        });
        tl.to(card.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' })
          .to(card.scale, { x: 1, y: 1, duration: 0.3, ease: 'power2.out' });
      },
    },
  };

  /* ── cinematic primitives ── */
  const primCleanups = [];
  if (config.cinematicPrimitives) {
    for (const p of config.cinematicPrimitives) {
      const r = ctx.primitives[p.name](group, p.params);
      if (r) primCleanups.push(r);
    }
  }

  /* ── cleanup ── */
  group.userData.cleanup = () => {
    primCleanups.forEach((c) => {
      if (c.cleanup) c.cleanup();
      if (c.timeline) c.timeline.kill();
    });
    geo.dispose();
    edgeGeo.dispose();
    mat.dispose();
    edgeMat.dispose();
  };

  return group;
}
